const items = $input.all();

if (!items.length || !items[0].json.StudentName) {
  return [{ json: { hasData: false } }];
}

// Group homework by student
const students = {};
items.forEach(item => {
  const name    = item.json.StudentName;
  const subject = item.json.Subject || 'Unknown';
  const status  = (item.json.Status || '').toLowerCase();

  if (!name) return;
  if (!students[name]) students[name] = {};
  if (!students[name][subject]) {
    students[name][subject] = { total: 0, submitted: 0, pending: 0, missing: 0 };
  }

  students[name][subject].total++;
  if (status === 'submitted') students[name][subject].submitted++;
  else if (status === 'missing') students[name][subject].missing++;
  else students[name][subject].pending++;
});

// Build analysis per student
const results = [];
Object.entries(students).forEach(([name, subjects]) => {
  const subjectAnalysis = [];
  const weakSubjects    = [];
  const strongSubjects  = [];

  Object.entries(subjects).forEach(([subject, data]) => {
    const completionRate = data.total > 0
      ? Math.round((data.submitted / data.total) * 100)
      : 0;

    const level = completionRate < 50  ? 'weak' :
                  completionRate < 75  ? 'average' : 'strong';

    subjectAnalysis.push({
      subject,
      total:          data.total,
      submitted:      data.submitted,
      pending:        data.pending,
      missing:        data.missing,
      completionRate,
      level
    });

    if (level === 'weak')    weakSubjects.push(subject);
    if (level === 'strong')  strongSubjects.push(subject);
  });

  results.push({
    studentName:     name,
    hasData:         true,
    subjectAnalysis: JSON.stringify(subjectAnalysis),
    weakSubjects:    weakSubjects.join(', ') || 'None',
    strongSubjects:  strongSubjects.join(', ') || 'None',
    totalSubjects:   subjectAnalysis.length,
    weakCount:       weakSubjects.length
  });
});

return results.map(r => ({ json: r }));

const student = $('Loop Over Items').item.json;
const analysis = JSON.parse(student.subjectAnalysis);

const subjectSummary = analysis.map(s =>
  `${s.subject}: ${s.submitted}/${s.total} submitted (${s.completionRate}% completion) — ${s.missing} missing`
).join('\n');

const prompt = `You are an educational analyst. Based on homework completion data, write a brief learning gap report for a student.

Student: ${student.studentName}
Homework completion by subject:
${subjectSummary}

Write a 3-4 sentence report covering:
1. Which subjects the student struggles with most
2. Which subjects they perform well in
3. One specific recommendation for improvement

Keep it concise, factual, and helpful for the tutor. No greetings, no sign-offs. Just the analysis.`;

return [{
  json: {
    studentName:     student.studentName,
    weakSubjects:    student.weakSubjects,
    strongSubjects:  student.strongSubjects,
    weakCount:       student.weakCount,
    subjectAnalysis: student.subjectAnalysis,
    ollamaBody: JSON.stringify({
      model:  'llama3.2:1b',
      prompt: prompt,
      stream: false
    })
  }
}];

const ollamaData  = $input.all()[0].json;
const studentData = $('Build Gap Prompt').item.json;
const aiAnalysis  = ollamaData.response || 'Analysis unavailable.';
const analysis    = JSON.parse(studentData.subjectAnalysis);

const subjectLines = analysis.map(s => {
  const emoji = s.level === 'weak'    ? '🔴' :
                s.level === 'average' ? '🟡' : '✅';
  return `${emoji} ${s.subject}: ${s.completionRate}% (${s.submitted}/${s.total} submitted, ${s.missing} missing)`;
}).join('\n');

const report = [
  `📊 Learning Gap Report — ${studentData.studentName}`,
  `Week of ${new Date().toLocaleDateString('en-GB')}`,
  '',
  '📚 Subject Breakdown:',
  subjectLines,
  '',
  `⚠️ Weak areas: ${studentData.weakSubjects}`,
  `💪 Strong areas: ${studentData.strongSubjects}`,
  '',
  '🤖 AI Analysis:',
  aiAnalysis.trim(),
  '',
  '─────────────────────'
].join('\n');

return [{ json: { report, studentName: studentData.studentName } }];
